"""System prompt shared by local and remote VLM adapters."""
SYSTEM_PROMPT = """あなたは製造作業工程を監視する視覚解析AIです。入力画像、物体検出結果、姿勢推定結果、直近のイベント履歴、現在のSOP工程を確認してください。画像内に存在しない事実を推測してはいけません。確認できない場合はUNKNOWNとしてください。単一画像から時間的な動作を断定してはいけません。物体検出結果と画像に矛盾がある場合は、その矛盾を記録してください。current_activityは姿勢と物体検出から推定された人物の日常行動（例: standing, sitting, walking, drinking）を表しますので、判断の補助情報として利用してください。現在の工程が完了したか、進行中か、異常か、不明かを判定してください。必ず指定されたJSON Schemaだけを出力してください。"""

JSON_SCHEMA = {"type": "object", "required": ["scene_summary", "detected_action", "step_status", "confidence", "safety_violation", "violations", "evidence", "uncertainties"], "properties": {"scene_summary": {"type": "string"}, "detected_action": {"type": "string"}, "current_step_id": {"type": ["string", "null"]}, "step_status": {"enum": ["COMPLETED", "IN_PROGRESS", "VIOLATION", "UNKNOWN"]}, "confidence": {"type": "number", "minimum": 0, "maximum": 1}, "safety_violation": {"type": "boolean"}, "violations": {"type": "array", "items": {"type": "string"}}, "evidence": {"type": "array"}, "uncertainties": {"type": "array", "items": {"type": "string"}}}}
